      'delivery@foodhub.local', crypt('demo1234', gen_salt('bf')),
      now(), now(), now(),
      '', '', '', '',
      '{"provider":"email","providers":["email"]}', '{}'
    );
    values (delivery_uid, 'delivery', 'Demo Delivery Partner', '9990002222');
    values (delivery_uid, false, 'bike');
